CREATE TYPE "ReservationStatus" AS ENUM ('active','released','consumed','expired');
CREATE TABLE "inventario" ("id" UUID NOT NULL,"batch_id" UUID NOT NULL,"product_id" UUID NOT NULL,"physical_kg" DECIMAL(12,3) NOT NULL,"available_kg" DECIMAL(12,3) NOT NULL,"stock_version" BIGINT NOT NULL DEFAULT 1,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "inventario_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "inventario_batch_id_key" ON "inventario"("batch_id"); CREATE INDEX "inventario_product_id_idx" ON "inventario"("product_id");
CREATE TABLE "reservas_inventario" ("id" UUID NOT NULL,"item_id" UUID NOT NULL,"quantity_kg" DECIMAL(12,3) NOT NULL,"status" "ReservationStatus" NOT NULL DEFAULT 'active',"expires_at" TIMESTAMPTZ(6) NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "reservas_inventario_pkey" PRIMARY KEY("id"));
CREATE INDEX "reservas_inventario_item_id_status_idx" ON "reservas_inventario"("item_id","status"); ALTER TABLE "reservas_inventario" ADD CONSTRAINT "reservas_inventario_item_id_fkey" FOREIGN KEY("item_id") REFERENCES "inventario"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
